// Test data for standalone runs -- the real caller is the main workflow's
// Accounts config, which passes one item like this per enabled LinkedIn
// account. account_id is the NUMERIC organization (company page) ID.
return [
  { json: { platform: 'LinkedIn', channel: 'Brand A', account_id: 'YOUR_LINKEDIN_ORG_ID', likes_label: 'Reactions', days: 14 } },
];

// Common landing point for both entry paths (the real "When Executed by
// Parent" caller, and "Test manually" for standalone testing), so the nodes
// downstream can reliably reference ONE upstream node by name regardless of
// which trigger actually ran.
return $input.all();

// Turns the org's recent posts into share-statistics requests. Posts have
// either a urn:li:share: or urn:li:ugcPost: id, and the statistics endpoint
// takes them via separate query params (shares / ugcPosts), so each type is
// chunked and requested separately.
const ctx = $('Prepare request').first().json;
const days = Number(ctx.days) || 14;
const orgUrn = String(ctx.account_id).startsWith('urn:')
  ? String(ctx.account_id)
  : `urn:li:organization:${ctx.account_id}`;

const enc = encodeURIComponent;
const orgQuery =
  `https://api.linkedin.com/rest/organizationalEntityShareStatistics` +
  `?q=organizationalEntity&organizationalEntity=${enc(orgUrn)}`;

const elements = Array.isArray($input.first().json.elements)
  ? $input.first().json.elements
  : [];

const cutoff = Date.now() - days * 24 * 60 * 60 * 1000;
const recent = elements.filter(
  p => p && p.id && (p.publishedAt || p.createdAt || 0) >= cutoff
);

const byParam = { shares: [], ugcPosts: [] };
recent.forEach(p => {
  const id = String(p.id);
  if (id.startsWith('urn:li:ugcPost:')) byParam.ugcPosts.push(id);
  else if (id.startsWith('urn:li:share:')) byParam.shares.push(id);
});

const CHUNK = 10;
const urls = [];
Object.entries(byParam).forEach(([param, ids]) => {
  for (let i = 0; i < ids.length; i += CHUNK) {
    const list = ids.slice(i, i + CHUNK).map(enc).join(',');
    urls.push(`${orgQuery}&${param}=List(${list})`);
  }
});

// Nothing to look up (no recent posts, or the post list itself failed): fall
// back to the plain org-level request so this node always emits at least one
// valid item and the chain never dead-ends. Its response has no per-post
// URN, so Normalize ignores it.
if (!urls.length) urls.push(orgQuery);

return urls.map(url => ({ json: { url }, pairedItem: 0 }));

// Maps LinkedIn organic org posts + their lifetime share statistics into the
// standard row schema the main report expects.
const ctx = $('Prepare request').first().json;
const days = Number(ctx.days) || 14;
const postsRes = $('Get org posts').first().json;

function skipped(reason) {
  return [{
    json: { platform: 'LinkedIn', channel: ctx.channel, skipped: true, reason },
    pairedItem: 0,
  }];
}

if (!Array.isArray(postsRes.elements)) {
  const detail = postsRes.error ? JSON.stringify(postsRes.error) : JSON.stringify(postsRes);
  return skipped('Could not list org posts: ' + detail.slice(0, 300));
}

// Per-post stats keyed by post URN. Posts with no actions/impressions are
// OMITTED from the response (LinkedIn docs) -> they're genuine zeros, but only
// if the stats calls themselves succeeded.
const stats = new Map();
let statsOk = true;

for (const item of $input.all()) {
  const r = item.json;
  const ok = typeof r.statusCode === 'number' && r.statusCode >= 200 && r.statusCode < 300 && r.body;
  if (!ok) { statsOk = false; continue; }
  for (const el of r.body.elements || []) {
    const key = el.share || el.ugcPost;
    if (key) stats.set(key, el.totalShareStatistics || {});
  }
}

function typeLabel(p) {
  if (p.reshareContext && p.reshareContext.parent) return 'Reshare';
  const c = p.content || {};
  if (c.media && c.media.id) {
    const id = String(c.media.id);
    if (id.startsWith('urn:li:video:')) return 'Video';
    if (id.startsWith('urn:li:image:')) return 'Photo';
    if (id.startsWith('urn:li:document:')) return 'Document';
    return 'Media';
  }
  if (c.multiImage) return 'Photo';
  if (c.article) return 'Article';
  if (c.poll) return 'Poll';
  return 'Text';
}

// Post commentary uses LinkedIn's "little" text format: mentions look like
// @[Name](urn:...), hashtags like {hashtag|\#|tag}, and reserved characters
// are backslash-escaped.
function cleanCommentary(text) {
  return String(text || '')
    .replace(/@\[([^\]]+)\]\([^)]*\)/g, '$1')
    .replace(/\{hashtag\|\\?#\|([^}]+)\}/g, '#$1')
    .replace(/\\([\\|{}@\[\]()<>#*_~])/g, '$1');
}

const cutoff = Date.now() - days * 24 * 60 * 60 * 1000;
const count = v => (statsOk ? Math.max(0, Number(v) || 0) : null);

const rows = postsRes.elements
  .filter(p => p && p.id && (p.lifecycleState || 'PUBLISHED') === 'PUBLISHED')
  .filter(p => (p.publishedAt || p.createdAt || 0) >= cutoff)
  .map(p => {
    const s = stats.get(p.id) || {};
    const type = typeLabel(p);
    const firstLine = cleanCommentary(p.commentary).split('\n').map(l => l.trim()).find(Boolean);
    const ts = p.publishedAt || p.createdAt || null;

    return {
      json: {
        platform: 'LinkedIn',
        channel: ctx.channel,
        account_id: ctx.account_id,
        likes_label: 'Reactions',
        id: String(p.id),
        title: (firstLine || `LinkedIn ${type}`).slice(0, 100),
        type,
        views: count(s.impressionCount),
        likes: count(s.likeCount),
        comments: count(s.commentCount),
        shares: count(s.shareCount),
        permalink: `https://www.linkedin.com/feed/update/${p.id}/`,
        created_at: ts ? new Date(ts).toISOString() : null,
        insights_ok: statsOk,
      },
      pairedItem: 0,
    };
  });

return rows.length ? rows : skipped(`No posts in the last ${days} days.`);
